using Microsoft.EntityFrameworkCore;
class BlogContext : DbContext
{
    public DbSet<Blog> Blogs => Set<Blog>();
    protected override void OnModelCreating(ModelBuilder modelBuilder)
    {
        modelBuilder.Entity<Blog>(entity =>
        {
            // Breaking change 1: EF 9 removed HasIndex for Cosmos (indexes are managed by Cosmos itself)
            // modelBuilder.Entity<Blog>().HasIndex(b => b.Name); -- REMOVED

            // Breaking change 2: EF 9 changes the discriminator property name from "Discriminator" to "$type"
            // To remain compatible with existing documents that use "Discriminator":
            entity.HasDiscriminator<string>("Discriminator");

            // Breaking change 3: EF 9 changes id format from "EntityType|KeyValue" to just "KeyValue"
            // To remain compatible with existing documents using "Blog|1" format:
            entity.HasPartitionKey(b => b.Id);
            entity.Property(b => b.Id)
                .ToJsonProperty("id")
                .HasValueGenerator<LegacyIdValueGenerator>();
        });
    }
}

// Value generator that preserves the legacy "Discriminator|Key" id format
