class SyncJob
{
    void Run(BlogContext context)
    {
        var blogs = context.Blogs.ToList();
        foreach (var b in blogs) { b.Name = b.Name.Trim(); }
        context.SaveChanges();

        // Breaking change 4: Raw SQL queries using "Discriminator" property still work because
        // we configured HasDiscriminator("Discriminator") above. If you had NOT done that,
        // you'd need to update queries from:
        //   SELECT * FROM c WHERE c.Discriminator = 'Blog'
        // to:
        //   SELECT * FROM c WHERE c["$type"] = 'Blog'
    }
}

